//! JSON API of the `events` resource, generated by
//! `forge generate resource` (and `forge generate scaffold`). Handlers stay
//! thin: authorize, decode the request, call [`EventService`], answer
//! JSON.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/v1/events?cursor=ID` | list, in creation order, `PAGE_SIZE` per page | `events:read` |
//! | `POST` | `/v1/events` | create: `201` with `Location` | `events:write` |
//! | `GET` | `/v1/events/{id}` | show | `events:read` |
//! | `PATCH` | `/v1/events/{id}` | change the members sent, with the `version` read | `events:write` |
//! | `DELETE` | `/v1/events/{id}?version=N` | delete the version read: `204` | `events:write` |
//!
//! Events belong to a tenant: the tenant is the one the bearer token was
//! issued for (`crate::adapters::http::api_access`), never a path, query or
//! header value, and every statement binds it.
//!
//! A stale `version` answers `409`, an invalid value `422` with a message
//! per member in `metadata`, an unknown `{id}` `404`. `PATCH` changes only
//! the members it names; `null` clears an optional one. Every route is
//! described in the OpenAPI document (`GET /openapi.json`, `forge openapi`).

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::core::{ErrorCategory, ForgeError, Timestamp, Uuid, Version};
use forge::http::{HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::openapi::{OpenApiSchema, Operation, Param, describe};
use forge::security::Permission;
use forge::tenancy::BearerDenied;
use forge::web::Patch;
use serde::{Deserialize, Serialize};

use crate::adapters::http::api_access::ApiTenantAccess;
use crate::application::use_cases::events::{
    EventError, EventService, READ_PERMISSION, WRITE_PERMISSION,
};
use crate::domain::entities::event::{Event, EventAttributes, EventId};

/// The collection's path.
pub const COLLECTION_PATH: &str = "/v1/events";

/// A event as the API answers it.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct EventJson {
    /// The event's UUIDv7.
    pub id: EventId,
    pub name: String,
    pub notes: Option<String>,
    pub starts_at: Timestamp,
    pub ends_at: Option<Timestamp>,
    pub capacity: i64,
    pub attendees: Option<i64>,
    pub public: bool,
    pub featured: Option<bool>,
    pub venue: Uuid,
    pub organizer: Option<Uuid>,
    /// The optimistic-locking version: `PATCH` and `DELETE` send it back.
    pub version: i64,
}

impl From<&Event> for EventJson {
    fn from(event: &Event) -> Self {
        let EventAttributes {
            name,
            notes,
            starts_at,
            ends_at,
            capacity,
            attendees,
            public,
            featured,
            venue,
            organizer,
        } = event.attributes().clone();
        Self {
            id: event.id(),
            name,
            notes,
            starts_at,
            ends_at,
            capacity,
            attendees,
            public,
            featured,
            venue,
            organizer,
            version: event.version().get(),
        }
    }
}

/// One page of events.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct EventList {
    pub items: Vec<EventJson>,
    /// The `cursor` of the next page; `null` on the last one.
    pub next_cursor: Option<EventId>,
}

/// The body of `POST`: every required member.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct NewEvent {
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
    pub starts_at: Timestamp,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ends_at: Option<Timestamp>,
    pub capacity: i64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub attendees: Option<i64>,
    pub public: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub featured: Option<bool>,
    pub venue: Uuid,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub organizer: Option<Uuid>,
}

impl From<NewEvent> for EventAttributes {
    fn from(body: NewEvent) -> Self {
        let NewEvent {
            name,
            notes,
            starts_at,
            ends_at,
            capacity,
            attendees,
            public,
            featured,
            venue,
            organizer,
        } = body;
        Self {
            name,
            notes,
            starts_at,
            ends_at,
            capacity,
            attendees,
            public,
            featured,
            venue,
            organizer,
        }
    }
}

/// The body of `PATCH`: the version read and the members to change. A member
/// left out stays as it is; `null` clears an optional one.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct EventChanges {
    /// The version the client last read.
    pub version: i64,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub name: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub notes: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub starts_at: Patch<Timestamp>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub ends_at: Patch<Timestamp>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub capacity: Patch<i64>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub attendees: Patch<i64>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub public: Patch<bool>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub featured: Patch<bool>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub venue: Patch<Uuid>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub organizer: Patch<Uuid>,
}

impl EventChanges {
    /// Applies the members sent to `attributes`; `null` for a required
    /// member is refused.
    fn apply(self, attributes: &mut EventAttributes) -> Result<(), ForgeError> {
        match self.name {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("name")),
            Patch::Value(value) => attributes.name = value,
        }
        match self.notes {
            Patch::Absent => {}
            Patch::Null => attributes.notes = None,
            Patch::Value(value) => attributes.notes = Some(value),
        }
        match self.starts_at {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("starts_at")),
            Patch::Value(value) => attributes.starts_at = value,
        }
        match self.ends_at {
            Patch::Absent => {}
            Patch::Null => attributes.ends_at = None,
            Patch::Value(value) => attributes.ends_at = Some(value),
        }
        match self.capacity {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("capacity")),
            Patch::Value(value) => attributes.capacity = value,
        }
        match self.attendees {
            Patch::Absent => {}
            Patch::Null => attributes.attendees = None,
            Patch::Value(value) => attributes.attendees = Some(value),
        }
        match self.public {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("public")),
            Patch::Value(value) => attributes.public = value,
        }
        match self.featured {
            Patch::Absent => {}
            Patch::Null => attributes.featured = None,
            Patch::Value(value) => attributes.featured = Some(value),
        }
        match self.venue {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("venue")),
            Patch::Value(value) => attributes.venue = value,
        }
        match self.organizer {
            Patch::Absent => {}
            Patch::Null => attributes.organizer = None,
            Patch::Value(value) => attributes.organizer = Some(value),
        }
        Ok(())
    }
}

/// The query of `GET /v1/events`.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ListQuery {
    cursor: Option<EventId>,
}

/// The query of `DELETE`: the version the client last read.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteQuery {
    version: i64,
}

/// What every handler shares.
struct EventApi {
    service: EventService,
    access: Arc<dyn ApiTenantAccess>,
    read: Permission,
    write: Permission,
}

/// Registers the routes. `access` decides who may call them (see
/// `crate::adapters::http::api_access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    service: EventService,
    access: Arc<dyn ApiTenantAccess>,
) -> Result<(), ComposeError> {
    let state = Arc::new(EventApi {
        service,
        access,
        read: Permission::new(READ_PERMISSION).map_err(ComposeError::other)?,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
    });
    let member = format!("{COLLECTION_PATH}/{{id}}");
    let id = || Param::path::<EventId>("id").doc("The event's ID.");
    route(
        router,
        &state,
        Method::GET,
        COLLECTION_PATH,
        list,
        operation(
            "listEvents",
            "List events, in creation order",
            READ_PERMISSION,
        )
        .param(
            Param::query::<Option<EventId>>("cursor").doc("The next_cursor of the previous page."),
        )
        .json::<EventList>(200)
        .errors([422]),
    )?;
    route(
        router,
        &state,
        Method::POST,
        COLLECTION_PATH,
        create,
        operation("createEvent", "Create a event", WRITE_PERMISSION)
            .request::<NewEvent>()
            .response(forge::openapi::Response::json::<EventJson>(201).header("Location")),
    )?;
    route(
        router,
        &state,
        Method::GET,
        &member,
        show,
        operation("getEvent", "Get a event", READ_PERMISSION)
            .param(id())
            .json::<EventJson>(200)
            .errors([400, 404]),
    )?;
    route(
        router,
        &state,
        Method::PATCH,
        &member,
        update,
        operation(
            "updateEvent",
            "Change some members of a event",
            WRITE_PERMISSION,
        )
        .param(id())
        .request::<EventChanges>()
        .json::<EventJson>(200)
        .errors([400, 404, 409]),
    )?;
    route(
        router,
        &state,
        Method::DELETE,
        &member,
        destroy,
        operation("deleteEvent", "Delete a event", WRITE_PERMISSION)
            .param(id())
            .param(
                Param::query::<i64>("version")
                    .required()
                    .doc("The version the client last read."),
            )
            .response(forge::openapi::Response::empty(204))
            .errors([400, 404, 409, 422]),
    )?;
    Ok(())
}

/// The description every route shares: bearer authentication, the
/// permission and the access policy's `503`.
fn operation(id: &str, summary: &str, permission: &str) -> Operation {
    Operation::new()
        .id(id)
        .summary(summary)
        .tag("events")
        .bearer()
        .permission(permission)
        .errors([503])
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<EventApi>,
    method: Method,
    path: &str,
    handler: H,
    operation: Operation,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<EventApi>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(
        method,
        path,
        describe(
            move |request: Request| handler(Arc::clone(&state), request),
            operation,
        ),
    )?;
    Ok(())
}

async fn list(state: Arc<EventApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let query: ListQuery = match forge::web::decode_query(&request) {
        Ok(query) => query,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.list(&context, query.cursor).await {
        Ok(page) => forge::web::json(
            StatusCode::OK,
            &EventList {
                items: page.events.iter().map(EventJson::from).collect(),
                next_cursor: page.next,
            },
        ),
        Err(error) => failure(error),
    }
}

async fn create(state: Arc<EventApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let body: NewEvent = match forge::web::decode_json_strict(&request) {
        Ok(body) => body,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.create(&context, body.into()).await {
        Ok(event) => {
            let mut response = forge::web::json(StatusCode::CREATED, &EventJson::from(&event));
            if let Ok(location) =
                HeaderValue::from_str(&format!("{COLLECTION_PATH}/{}", event.id()))
            {
                response.headers_mut().insert(header::LOCATION, location);
            }
            response
        }
        Err(error) => failure(error),
    }
}

async fn show(state: Arc<EventApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    match state.service.find(&context, id).await {
        Ok(event) => forge::web::json(StatusCode::OK, &EventJson::from(&event)),
        Err(error) => failure(error),
    }
}

async fn update(state: Arc<EventApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let changes: EventChanges = match forge::web::decode_json_strict(&request) {
        Ok(changes) => changes,
        Err(failure) => return forge::web::error(&failure),
    };
    let expected = match Version::new(changes.version) {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    // The stored attributes with the members sent; the update itself checks
    // that the version read is still the stored one.
    let mut attributes = match state.service.find(&context, id).await {
        Ok(event) => event.attributes().clone(),
        Err(error) => return failure(error),
    };
    if let Err(failure) = changes.apply(&mut attributes) {
        return forge::web::error(&failure);
    }
    match state
        .service
        .update(&context, id, expected, attributes)
        .await
    {
        Ok(event) => forge::web::json(StatusCode::OK, &EventJson::from(&event)),
        Err(error) => failure(error),
    }
}

async fn destroy(state: Arc<EventApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let expected = match forge::web::decode_query::<DeleteQuery>(&request)
        .and_then(|query| Version::new(query.version))
    {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.delete(&context, id, expected).await {
        Ok(()) => Response::empty(StatusCode::NO_CONTENT),
        Err(error) => failure(error),
    }
}

/// The route's `{id}`, when it is a UUIDv7.
fn path_id(request: &Request) -> Option<EventId> {
    request.path_param_as("id").ok()
}

/// `400 invalid_id`: the `{id}` is not a UUIDv7.
fn invalid_id() -> Response {
    let failure = ForgeError::new(
        ErrorCategory::Validation,
        "invalid_id",
        "the event ID is not a UUIDv7",
    );
    forge::web::json(StatusCode::BAD_REQUEST, &failure.report())
}

/// The JSON answer to a failed use case.
fn failure(error: EventError) -> Response {
    match error {
        EventError::Invalid(violations) => {
            let mut failure = ForgeError::new(
                ErrorCategory::Validation,
                "validation_failed",
                "the event is invalid",
            );
            for (field, violation) in violations.iter() {
                failure = failure.with_metadata(field.name(), violation.to_string());
            }
            forge::web::error(&failure)
        }
        EventError::NotFound => forge::web::error(&ForgeError::new(
            ErrorCategory::NotFound,
            "event_not_found",
            "event not found",
        )),
        EventError::Conflict => forge::web::error(&ForgeError::new(
            ErrorCategory::Conflict,
            "event_conflict",
            "the event was changed by someone else",
        )),
        EventError::Forbidden => forge::web::bearer_refusal(BearerDenied::Forbidden),
        // Logged with its cause chain; the client sees a generic report.
        EventError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "event_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// `null` for a member that cannot be empty.
fn not_null(member: &str) -> ForgeError {
    ForgeError::new(
        ErrorCategory::Validation,
        "validation_failed",
        "the event is invalid",
    )
    .with_metadata(member, "can't be null")
}
